@($roots=@('.\frontend\src','.\mobile\lib','.\backend\ReliefNexus.API'); $files=Get-ChildItem $roots -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.ts','.tsx','.js','.jsx','.dart','.cs','.json','.html','.css','.scss' }; foreach($f in $files){ $s=[IO.File]::ReadAllText($f.FullName); $o=$s; $s=[regex]::Replace($s,'[^\x00-\x7F]',''); if($s -ne $o){[IO.File]::WriteAllText($f.FullName,$s,[Text.UTF8Encoding]::new($false)); Write-Host ('Cleaned: '+$f.FullName) -ForegroundColor Yellow} }; Write-Host 'ASCII cleanup completed.' -ForegroundColor Green)
